use std::collections::HashSet;

/// Returns true if `element` occurs at least once in `list`.
/// Does not modify `list` and always terminates.
fn contains(list: &Vec<i32>, element: i32) -> bool {
    for &x in list.iter() {
        if x == element {
            return true;
        }
    }
    false
}

/// Returns true iff `list1` and `list2` share at least one common value.
/// Does not modify the input vectors and always terminates.
///
/// Implementation detail:
/// - Build a set of elements from the smaller list, then probe with the other list.
/// - This is O(n + m) expected time, O(min(n, m)) extra space.
fn has_common_element(list1: &Vec<i32>, list2: &Vec<i32>) -> bool {
    if list1.is_empty() || list2.is_empty() {
        return false;
    }

    // Build the set from the smaller list to minimize memory usage.
    let (small, large) = if list1.len() <= list2.len() {
        (list1, list2)
    } else {
        (list2, list1)
    };

    let set: HashSet<i32> = small.iter().copied().collect();
    for &x in large.iter() {
        if set.contains(&x) {
            return true;
        }
    }
    false
}

